/bin/bash -c "apply_patch <<'PATCH'
*** Begin Patch
*** Update File: app/featured-product-link.tsx
@@
 import Link from 'next/link'
-import { useState } from 'react'
+import { useRouter } from 'next/navigation'

 export function FeaturedProductLink() {
-  const [prefetchOnIntent, setPrefetchOnIntent] = useState(false)
+  const router = useRouter()

-  function enablePrefetch() {
-    setPrefetchOnIntent(true)
+  function prefetchProduct() {
+    router.prefetch('/product')
   }

   return (
     <Link
       href=\"/product\"
-      prefetch={prefetchOnIntent ? null : false}
-      onMouseEnter={enablePrefetch}
-      onFocus={enablePrefetch}
-      onTouchStart={enablePrefetch}
+      prefetch={false}
+      onMouseEnter={prefetchProduct}
+      onFocus={prefetchProduct}
+      onTouchStart={prefetchProduct}
*** End Patch
PATCH
npx tsc --noEmit --incremental false"

